#!/usr/bin/env python3
import os
import json
import re
import time
import threading
from datetime import datetime
from pathlib import Path
from typing import Dict, Any, Generator, Optional
import urllib.request
from concurrent.futures import ThreadPoolExecutor

CONFIG_FILE = "hun_config.json"
OUTPUT_DIR = "output"
OUTPUT_JSONL = f"{OUTPUT_DIR}/forditottak_tiszta.jsonl"
STATS_FILE = f"{OUTPUT_DIR}/stats.json"
DATASET_URL = "https://huggingface.co/datasets/neulab/agent-data-collection/resolve/main/orca_agentinstruct/full_raw.jsonl"
API_KEYS = [os.environ.get(f"CEREBRAS_API_KEY_{i}") for i in range(1, 6)]
jsonl_lock = threading.Lock()
stats_lock = threading.Lock()
stats: Dict[str, Any] = {
    "total_processed": 0,
    "saved_cleaned": 0,
    "filtered_english": 0,
    "filtered_backticks": 0,
    "filtered_short": 0,
    "errors": 0,
    "start_time": datetime.now().isoformat()
}
BACKTICK_PATTERN = r"``````|`[^`]*`"
REFUSAL_PATTERNS = [
    r"To provide an accurate translation",
    r"I need to know the target language",
    r"I cannot provide",
    r"unable to translate",
]

def load_config() -> Dict[str, Any]:
    if not Path(CONFIG_FILE).exists():
        return {}
    with open(CONFIG_FILE, "r", encoding="utf-8") as f:
        return json.load(f)

def ensure_output_dir() -> None:
    Path(OUTPUT_DIR).mkdir(parents=True, exist_ok=True)

def initialize_clients():
    from cerebras.cloud.sdk import Cerebras
    clients = []
    for i, api_key in enumerate(API_KEYS, 1):
        if api_key:
            try:
                client = Cerebras(api_key=api_key)
                clients.append(client)
            except Exception as e:
                print(f"✗ API {i}: {e}")
    return clients

def stream_dataset() -> Generator[Dict[str, Any], None, None]:
    while True:
        try:
            with urllib.request.urlopen(DATASET_URL, timeout=60) as response:
                for line in response:
                    line = line.decode("utf-8").strip()
                    if line:
                        try:
                            yield json.loads(line)
                        except Exception:
                            continue
        except Exception as e:
            print(f"⚠ Kapcsolati hiba, újrapróbálkozás: {e}")
            time.sleep(5)

def is_english_response(text: str) -> bool:
    if not text or len(text) < 10:
        return False
    for pattern in REFUSAL_PATTERNS:
        if re.search(pattern, text, flags=re.IGNORECASE):
            return True
    return False

def remove_backticks(text: str) -> str:
    return re.sub(BACKTICK_PATTERN, "", text).strip()

def clean_translation(translation: Any) -> Optional[Dict[str, Any]]:
    if isinstance(translation, dict):
        if "eredeti_valasz" in translation:
            return None
        text = json.dumps(translation, ensure_ascii=False)
    else:
        text = str(translation)
    if is_english_response(text):
        return None
    if len(text) < 20:
        return None
    cleaned = remove_backticks(text)
    cleaned = re.sub(r"\s+", " ", cleaned).strip()
    return {"tisztitott_forditas": cleaned}

def _build_completion_kwargs(model_id: str, model_config: Dict[str, Any], messages: Any) -> Dict[str, Any]:
    kwargs: Dict[str, Any] = {
        "messages": messages,
        "model": model_id,
        "stream": True,
    }
    max_tokens = (
        model_config.get("max_tokens")
        or model_config.get("max_completion_tokens")
        or model_config.get("max_tokensz")
    )
    if max_tokens is not None:
        try:
            kwargs["max_tokens"] = int(max_tokens)
        except Exception:
            pass
    temperature = model_config.get("homerseklet", model_config.get("temperature"))
    if temperature is not None:
        try:
            kwargs["temperature"] = float(temperature)
        except Exception:
            pass
    top_p = model_config.get("top_p")
    if top_p is not None:
        try:
            kwargs["top_p"] = float(top_p)
        except Exception:
            pass
    return kwargs

def _extract_stream_content(chunk: Any) -> str:
    try:
        return chunk.choices[0].delta.content or ""
    except Exception:
        pass
    try:
        if isinstance(chunk, dict):
            delta = chunk.get("choices", [{}])[0].get("delta", {})
            return delta.get("content", "") or ""
    except Exception:
        pass
    try:
        if hasattr(chunk, "choices") and len(chunk.choices) > 0 and hasattr(chunk.choices[0], "message"):
            return getattr(chunk.choices[0].message, "content", "") or ""
    except Exception:
        pass
    return ""

def translate_to_hungarian(client, model_id, model_config, data, api_idx) -> str:
    data_text = json.dumps(data, ensure_ascii=False, indent=2)
    prompt = f"""Fordítsd le a következő angol nyelvű adatokat magyarra. 
Tartsd meg az eredeti JSON szerkezetet és csak a szövegeket fordítsd. 
Küldj vissza csak a lefordított JSON-t semmi más nélkül.

Eredeti adatok:
{data_text}"""
    try:
        messages = [
            {"role": "system", "content": "Te egy professzionális fordító vagy. Fordítsd le a szövegeket angolról magyarra, megtartva a JSON formátumot."},
            {"role": "user", "content": prompt},
        ]
        kwargs = _build_completion_kwargs(model_id, model_config, messages)
        stream = client.chat.completions.create(**kwargs)
        parts = []
        for chunk in stream:
            content = _extract_stream_content(chunk)
            if content:
                parts.append(content)
        return "".join(parts)
    except Exception as e:
        return f"Hiba: {str(e)}"

def parse_json(text: str) -> Dict[str, Any]:
    try:
        start = text.find("{")
        end = text.rfind("}")
        if start >= 0 and end >= 0:
            return json.loads(text[start : end + 1])
    except Exception:
        pass
    return {"eredeti_valasz": text}

def save_to_jsonl(entry: Dict[str, Any]) -> None:
    with jsonl_lock:
        with open(OUTPUT_JSONL, "a", encoding="utf-8") as f:
            f.write(json.dumps(entry, ensure_ascii=False) + "\n")

def update_stats(key: str, increment: int = 1) -> None:
    with stats_lock:
        stats[key] = stats.get(key, 0) + increment

def _get_model_config(config: Dict[str, Any]) -> Dict[str, Any]:
    if isinstance(config, dict):
        mc = config.get("modelek", {}).get("modell2")
        if isinstance(mc, dict):
            return mc
    env_model = os.environ.get("CEREBRAS_MODEL_ID", "")
    return {
        "azonosito": env_model,
        "max_tokens": 2048,
        "homerseklet": 0.3,
        "top_p": 0.9,
    }

def process_item(client, api_idx: int, item_idx: int, data: Dict[str, Any], config: Dict[str, Any]) -> None:
    try:
        update_stats("total_processed")
        model_config = _get_model_config(config)
        model_id = model_config.get("azonosito", "")
        if not model_id:
            update_stats("errors")
            return
        response = translate_to_hungarian(client, model_id, model_config, data, api_idx)
        translation = parse_json(response)
        cleaned = clean_translation(translation)
        if cleaned is None:
            if is_english_response(str(translation)):
                update_stats("filtered_english")
            elif len(str(translation)) < 20:
                update_stats("filtered_short")
            else:
                update_stats("filtered_backticks")
            return
        entry = {
            "timestamp": datetime.now().isoformat(),
            "index": item_idx,
            "api": api_idx,
            "modell": model_id,
            "magyar": cleaned["tisztitott_forditas"],
            "nyelvezet": "magyar",
        }
        save_to_jsonl(entry)
        update_stats("saved_cleaned")
        if stats["saved_cleaned"] % 100 == 0:
            print(f"✓ {stats['saved_cleaned']} mentve | Feldolgozva: {stats['total_processed']} | Szűrt: {stats['filtered_english']+stats['filtered_backticks']+stats['filtered_short']}")
    except Exception:
        update_stats("errors")

def run() -> None:
    print("=" * 80)
    print("FORDÍTÁS + TISZTÍTÁS EGYBEN - SOSEM ÁLL MEG")
    print("=" * 80)
    config = load_config()
    ensure_output_dir()
    clients = initialize_clients()
    if not clients:
        print("✗ Nincs elérhető API!")
        return
    print(f"\n✓ API kliensek: {len(clients)}")
    print(f"✓ Kimeneti fájl: {OUTPUT_JSONL}")
    print(f"✓ Feldolgozás megkezdése... (Ctrl+C a leállításhoz)\n")
    item_idx = 0
    futures = {}
    try:
        with ThreadPoolExecutor(max_workers=len(clients)) as executor:
            for item in stream_dataset():
                client = clients[item_idx % len(clients)]
                api_idx = (item_idx % len(clients)) + 1
                future = executor.submit(
                    process_item,
                    client,
                    api_idx,
                    item_idx,
                    item,
                    config,
                )
                futures[future] = item_idx
                item_idx += 1
                done_futures = []
                for f in futures:
                    if f.done():
                        try:
                            f.result()
                        except Exception as e:
                            print(f"✗ Hiba {futures[f]}: {e}")
                        done_futures.append(f)
                for f in done_futures:
                    del futures[f]
    except KeyboardInterrupt:
        print(f"\n\n✓ LEÁLLÍTVA - Végső statisztika mentése...\n")
    try:
        for future in futures:
            future.result(timeout=30)
    except Exception:
        pass
    stats["end_time"] = datetime.now().isoformat()
    with open(STATS_FILE, "w", encoding="utf-8") as f:
        json.dump(stats, f, ensure_ascii=False, indent=2)
    print(f"\n{'=' * 80}")
    print("✓ Feldolgozás vége!")
    print(f"✓ Összes feldolgozva: {stats['total_processed']}")
    print(f"✓ Mentve (tisztított): {stats['saved_cleaned']}")
    print(f"✓ Szűrt angol: {stats['filtered_english']}")
    print(f"✓ Szűrt backticks: {stats['filtered_backticks']}")
    print(f"✓ Szűrt rövid: {stats['filtered_short']}")
    print(f"✓ Hibák: {stats['errors']}")
    print(f"✓ JSONL fájl: {OUTPUT_JSONL}")
    print(f"✓ Statisztika: {STATS_FILE}")
    print(f"{'=' * 80}")

if __name__ == "__main__":
    run()

